const user = { name: 'Ada', age: 36, admin: true };

const text = JSON.stringify(user);
console.log(text);          // {"name":"Ada","age":36,"admin":true}
console.log(typeof text);   // string

const back = JSON.parse(text);
console.log(back.name);     // Ada
console.log(back === user); // false — a new object

const data = {
  id: 1,
  run: () => 'hi',   // dropped
  note: undefined,    // dropped
  when: new Date('2020-01-01')
};

const text = JSON.stringify(data);
console.log(text); // {"id":1,"when":"2020-01-01T00:00:00.000Z"}

const revived = JSON.parse(text, (key, value) =>
  key === 'when' ? new Date(value) : value
);
console.log(revived.when instanceof Date); // true

