solution.code:
function safeParse(text) {
  try {
    return JSON.parse(text);
  } catch (e) {
    return null;
  }
}

console.log(safeParse('{"a":1}'));
console.log(safeParse('{bad json}'));
console.log(safeParse('[1,2,3]'));

